import itertools
import statistics


def task_func(elements, subset_size):
    """Return the mean, median, and mode of fixed-size subset sums."""
    sums = [sum(subset) for subset in itertools.combinations(elements, subset_size)]
    return {
        'mean': statistics.mean(sums),
        'median': statistics.median(sums),
        'mode': statistics.mode(sums),
    }

