import warnings
import sqlite3
from contextlib import closing

import pandas as pd


def task_func(db_path, query, warn_large_dataset=True):
    """Fetch an SQLite query as a DataFrame, optionally warning on large results."""
    try:
        with closing(sqlite3.connect(db_path)) as connection:
            data = pd.read_sql_query(query, connection)
    except Exception as exc:
        raise Exception(
            f"Error fetching data from the database: {exc}"
        ) from exc

    if warn_large_dataset and len(data) > 10000:
        warnings.warn("The data contains more than 10000 rows.")

    return data

from itertools import cycle
from random import choice, seed


def task_func(n_colors, colors=['Red', 'Green', 'Blue', 'Yellow', 'Purple'], rng_seed=None):
    """Return alternating cyclic and random colors, starting with a cyclic color."""
    if n_colors <= 0:
        return []

    seed(rng_seed)
    cyclic_colors = cycle(colors)
    return [
        next(cyclic_colors) if i % 2 == 0 else choice(colors)
        for i in range(n_colors)
    ]

import collections
