import string


def task_func(length=100):
    """Generate random ASCII letters and return their character counts."""
    if length < 0:
        raise ValueError("length must be nonnegative")
    generated = ''.join(random.choices(
        string.ascii_uppercase + string.ascii_lowercase, k=length
    ))
    return dict(collections.Counter(generated))

