from collections import defaultdict
from random import randint


def task_func(dict1):
    """Return salary lists for department codes beginning with 'EMP$$'.

    Salaries are random integers from 30000 through 100000, inclusive.
    """
    employee_data = defaultdict(list)
    for department, employee_count in dict1.items():
        if department.startswith('EMP$$'):
            employee_data[department] = [
                randint(30000, 100000) for _ in range(employee_count)
            ]
    return dict(employee_data)

import ast
import os
import glob

DIRECTORY = 'data'


def task_func(directory):
    """Read dictionary literals from the directory's text files."""
    dictionaries = []
    pattern = os.path.join(glob.escape(os.fspath(directory)), '*.txt')
    for filename in glob.glob(pattern):
        with open(filename, 'r', encoding='utf-8') as file:
            content = file.read()
        try:
            value = ast.literal_eval(content)
        except (SyntaxError, ValueError) as exc:
            raise ValueError(
                f'Invalid dictionary representation in {filename!r}'
            ) from exc
        if not isinstance(value, dict):
            raise ValueError(
                f'Invalid dictionary representation in {filename!r}'
            )
        dictionaries.append(value)
    return dictionaries

