import numpy as np
import pandas as pd
from datetime import datetime

DATE_FORMAT = '%Y-%m-%d %H:%M:%S'


def task_func(result):
    """Return statistics for from_user values and the current local time."""
    values = [item['from_user'] for item in result if 'from_user' in item]
    if not values:
        summary = dict.fromkeys(('mean', 'median', 'min', 'max', 'std'), np.nan)
    else:
        try:
            data = np.asarray(values)
        except (TypeError, ValueError) as exc:
            raise ValueError('from_user values must be numeric') from exc
        if data.ndim != 1 or data.dtype.kind not in 'biufc':
            raise ValueError('from_user values must be numeric')
        summary = {
            'mean': np.mean(data),
            'median': np.median(data),
            'min': np.min(data),
            'max': np.max(data),
            'std': np.std(data),
        }
    summary['current_time'] = datetime.now().strftime(DATE_FORMAT)
    return pd.Series(summary)

import os
import shutil
import csv


def task_func(target_value='332', csv_dir='./csv_files/', processed_dir='./processed_files/', simulate=False):
    """Find the first matching row in each CSV and optionally move the files."""
    filenames = os.listdir(csv_dir)
    if not simulate:
        os.makedirs(processed_dir, exist_ok=True)

    result = {}
    for filename in filenames:
        source = os.path.join(csv_dir, filename)
        if not filename.endswith('.csv') or not os.path.isfile(source):
            continue

        with open(source, newline='') as stream:
            for index, row in enumerate(csv.reader(stream)):
                if row and row[0] == target_value:
                    result[filename] = index
                    break

        if not simulate:
            shutil.move(source, os.path.join(processed_dir, filename))

    return result

