import hashlib
import os
import re

OUTPUT_DIR = './output'


def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    """Return matching file paths mapped to SHA256 hexadecimal hashes."""
    regex = re.compile(pattern)
    results = {}
    for root, _, filenames in os.walk(directory):
        for filename in filenames:
            if regex.search(filename) is None:
                continue
            path = os.path.join(root, filename)
            digest = hashlib.sha256()
            with open(path, 'rb') as source:
                for chunk in iter(lambda: source.read(65536), b''):
                    digest.update(chunk)
            results[path] = binascii.hexlify(digest.digest()).decode('ascii')
    return results

