import collections
import csv
import numpy as np


def task_func(file_name):
    """Return each CSV column's most common value, breaking ties alphabetically.

    Numeric columns produce numeric values. Files without data rows return {}.
    """
    with open(file_name, newline='', encoding='utf-8') as stream:
        reader = csv.reader(stream)
        headers = next(reader, None)
        if headers is None:
            return {}
        rows = [row for row in reader if row]

    if not rows:
        return {}

    data = np.asarray(rows, dtype=str)
    result = {}
    for index, name in enumerate(headers):
        column = data[:, index]
        # Infer types independently so text columns do not stringify numbers
        # in other columns. Convert NumPy scalars to ordinary Python values.
        for dtype in (np.int64, np.float64):
            try:
                values = column.astype(dtype).tolist()
                break
            except (ValueError, OverflowError):
                continue
        else:
            values = column.tolist()

        counts = collections.Counter(values)
        result[name] = min(
            counts, key=lambda value: (-counts[value], str(value))
        )

    return result

