import random
import string


def task_func(length: int, predicates: list, seed: int = None):
    """Generate random text and evaluate its requested characteristics."""
    if length < 0:
        raise ValueError("length must be nonnegative")

    character_groups = {
        'has_uppercase': string.ascii_uppercase,
        'has_lowercase': string.ascii_lowercase,
        'has_special_chars': string.punctuation,
        'has_numbers': string.digits,
    }
    selected_groups = {
        predicate: character_groups[predicate]
        for predicate in predicates
    }

    if seed is not None:
        random.seed(seed)
    alphabet = string.ascii_letters + string.digits + string.punctuation
    text = ''.join(random.choices(alphabet, k=length))
    characteristics = {
        predicate: any(char in group for char in text)
        for predicate, group in selected_groups.items()
    }
    return text, characteristics

