def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    """Transfer matching files and return the names successfully moved."""
    os.makedirs(DEST_DIR, exist_ok=True)
    transferred_files = []

    for extension in EXTENSIONS:
        pattern = os.path.join(
            glob.escape(SOURCE_DIR), '*' + glob.escape(extension)
        )
        for source_path in glob.glob(pattern):
            if not os.path.isfile(source_path):
                continue
            filename = os.path.basename(source_path)
            try:
                shutil.move(source_path, os.path.join(DEST_DIR, filename))
            except Exception as exc:
                warnings.warn(
                    f'Could not transfer {filename}: {exc}', stacklevel=2
                )
            else:
                transferred_files.append(filename)

    return transferred_files

