import random
import string


def task_func(length: int, predicates: list, seed: int = None):
    """Generate random ASCII text and evaluate its requested characteristics."""
    if length < 0:
        raise ValueError("length must be nonnegative")

    tests = {
        'has_uppercase': str.isupper,
        'has_lowercase': str.islower,
        'has_special_chars': lambda char: char in string.punctuation,
        'has_numbers': str.isdigit,
    }
    requested = dict.fromkeys(predicates)
    for predicate in requested:
        if predicate not in tests:
            raise KeyError(predicate)

    if seed is not None:
        random.seed(seed)
    alphabet = string.ascii_letters + string.digits + string.punctuation
    text = ''.join(random.choices(alphabet, k=length))
    characteristics = {
        predicate: any(tests[predicate](char) for char in text)
        for predicate in requested
    }
    return text, characteristics

